ALTER TABLE finance_settlements DROP FOREIGN KEY fk_finance_settlement_funding,DROP CHECK ck_finance_settlement_origin;
DELETE FROM module_event_outbox WHERE source_module='finance' AND (event_type LIKE 'finance.advance.%' OR event_type LIKE 'finance.advance_file.%' OR entity_id IN (SELECT id FROM finance_titles WHERE JSON_EXTRACT(payload,'$.advanceLink') IS NOT NULL));
DELETE FROM finance_history WHERE entity_type IN ('advance','advance_file') OR (entity_type='title' AND entity_id IN (SELECT id FROM finance_titles WHERE JSON_EXTRACT(payload,'$.advanceLink') IS NOT NULL));
UPDATE finance_bank_entries SET settlement_id=NULL,revision=revision+1 WHERE settlement_id IN (SELECT id FROM finance_settlements WHERE advance_id IS NOT NULL OR title_id IN (SELECT id FROM finance_titles WHERE JSON_EXTRACT(payload,'$.advanceLink') IS NOT NULL));
DELETE FROM finance_cash_movements WHERE source_id IN (SELECT id FROM finance_settlements WHERE advance_id IS NOT NULL OR title_id IN (SELECT id FROM finance_titles WHERE JSON_EXTRACT(payload,'$.advanceLink') IS NOT NULL));
DELETE FROM finance_settlements WHERE advance_id IS NOT NULL OR title_id IN (SELECT id FROM finance_titles WHERE JSON_EXTRACT(payload,'$.advanceLink') IS NOT NULL);
ALTER TABLE finance_settlements DROP FOREIGN KEY fk_finance_settlement_advance,DROP COLUMN advance_id,DROP COLUMN funding_settlement_id,DROP COLUMN settlement_kind;
DELETE FROM finance_private_files WHERE title_id IN (SELECT id FROM finance_titles WHERE JSON_EXTRACT(payload,'$.advanceLink') IS NOT NULL);
DROP TABLE finance_advance_files;
DROP TABLE finance_advance_origins;
DROP TABLE finance_advances;
DELETE FROM finance_titles WHERE JSON_EXTRACT(payload,'$.advanceLink') IS NOT NULL;
DELETE FROM finance_categories WHERE nature IN ('advance_out','advance_return');
DELETE FROM finance_requests;
